public static partial class MirrorFrontSuspension {
 static object HubPartState(ModelDoc2 part){return new{color=part.MaterialPropertyValues,bodies=((object[])((PartDoc)part).GetBodies2(-1,false)).Cast<Body2>().Select(b=>new{name=b.Name,mass=b.GetMassProperties(1),box=b.GetBodyBox(),color=b.MaterialPropertyValues2,faces=((object[])b.GetFaces()).Cast<Face2>().Select(f=>new{area=f.GetArea(),box=f.GetBox(),color=f.HasMaterialPropertyValues()?f.GetMaterialPropertyValues2(1,null):null}).ToArray()}).ToArray()};}
 public static void AuditHubChanges(int pid,string output){
  app=(ISldWorks)typeof(CurrentAssignmentInspectionTest).GetMethod("Find",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{pid});folder=Path.Combine(hubRoot,"assembly");Load();var rows=new List<object>();
  foreach(var h in record.Hashes.Where(p=>Hash(p.Key)!=p.Value)){
   int e=0,w=0;var p=app.GetOpenDocumentByName(h.Key) as ModelDoc2;bool own=p==null;if(own)p=app.OpenDoc6(h.Key,1,3,"",ref e,ref w) as ModelDoc2;if(p==null)throw new Exception("Cannot inspect changed part "+e);try{var review=app.GetOpenDocumentByName(record.Files[h.Key]) as ModelDoc2;if(review==null)throw new Exception("Review part missing");var a=HubPartState(p);var b=HubPartState(review);rows.Add(new{path=h.Key,review=record.Files[h.Key],hash=Hash(h.Key),same=json.Serialize(a)==json.Serialize(b),current=a,reviewed=b});Console.WriteLine("Audited "+Path.GetFileName(h.Key));}finally{if(own)app.CloseDoc(p.GetTitle());}
  }Write("hub-changed-parts-audit.json",rows);Activate(model);
 }
 static Dictionary<string,object>[] HubArray(Dictionary<string,object> d,string key){object v;return d.TryGetValue(key,out v)&&v is object[]?((object[])v).Cast<Dictionary<string,object>>().ToArray():new Dictionary<string,object>[0];}
 static Dictionary<string,object> HubRead(string path){return (Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(path));}
 static int HubValidate(object value){
  var seen=new HashSet<string>();Action<object> visit=null;visit=o=>{var d=o as Dictionary<string,object>;if(d!=null){object k,r,c;if(d.TryGetValue("Kind",out k)&&object.Equals(k,"body")&&d.TryGetValue("Reference",out r)&&d.TryGetValue("ComponentReference",out c)&&seen.Add((string)c+"|"+(string)r)){if(!(Resolve(model,(string)r) is Body2)||!(Resolve(model,(string)c) is Component2))throw new Exception("Merged assignment does not resolve");}foreach(var child in d.Values)visit(child);}else if(o is object[])foreach(var child in (object[])o)visit(child);};visit(value);return seen.Count;
 }
 static void HubClose(HashSet<string> paths){foreach(var d in (app.GetDocuments() as object[]??new object[0]).Cast<ModelDoc2>().Where(d=>paths.Contains(d.GetPathName())).OrderBy(d=>d is AssemblyDoc?0:1).Select(d=>new{Path=d.GetPathName(),Title=d.GetTitle()}).ToArray())if(app.GetOpenDocumentByName(d.Path)!=null)app.CloseDoc(d.Title);}
 static void HubOpen(string path){int e=0,w=0;model=app.OpenDoc6(path,2,1,"",ref e,ref w) as ModelDoc2;if(model==null)throw new Exception("Cannot open merged companion: "+e);Activate(model);instances=Components().ToDictionary(c=>c.GetID());model.EditRebuild3();}
 public static void MergeHubs(int pid,string output){
  app=(ISldWorks)typeof(CurrentAssignmentInspectionTest).GetMethod("Find",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{pid});code=Assembly.LoadFrom(Path.Combine(output,"beamng.cad.dll"));folder=Path.Combine(hubRoot,"assembly");app.CommandInProgress=true;
  try{HubMergeCore();}finally{app.CommandInProgress=false;}
 }
 static void HubMergeCore(){
  Load();var equivalents=HubRead(Path.Combine(folder,"hub-equivalent-resaves.json"));if(!object.Equals(equivalents["status"],"passed")||!string.Equals(Hash(Path.Combine(folder,"hub-changed-parts-audit.json")),(string)equivalents["audit_sha256"],StringComparison.OrdinalIgnoreCase))throw new Exception("Resave comparison evidence is invalid");foreach(var h in (Dictionary<string,object>)equivalents["hashes"]){if(!record.Hashes.ContainsKey(h.Key))throw new Exception("Unexpected resaved dependency");record.Hashes[h.Key]=(string)h.Value;}CheckOriginals();if(instances.Count!=76||Mates().Count()!=71||MateFailures()!=0)throw new Exception("Review structure/mates changed");
  var original=record;var target=original.Source;var root=Path.GetDirectoryName(target);var oldPaths=new HashSet<string>(original.Files.Keys,StringComparer.OrdinalIgnoreCase);
  if((app.GetDocuments() as object[]??new object[0]).Cast<ModelDoc2>().Any(d=>oldPaths.Contains(d.GetPathName())&&d.GetSaveFlag()))throw new Exception("Working documents have unsaved changes");
  var reviewed=HubRead(original.Copy+".beamng-project.json");if(HubValidate(reviewed)!=1000)throw new Exception("Review assignments changed");
  var wheels=HubArray(reviewed,"Components").Where(g=>object.Equals(g["MvpRole"],"rl_wheel")||object.Equals(g["MvpRole"],"rr_wheel")).ToDictionary(g=>(string)g["Id"],g=>HubReadClone(g));
  foreach(var g in wheels.Values){var ss=HubArray(g,"Selections");if(ss.Length!=3)throw new Exception("Wheel missing restored hub");HubSeatCheck((Body2)Resolve(model,(string)ss.Single(s=>((string)s["Name"]).Contains("RestoredRearHub"))["Reference"]));}
  var oldProject=HubRead(target+".beamng-project.json");var receipt=HubRead(Path.Combine(root,"working-assembly.json"));var lineagePath=Path.Combine(root,"rear-donor-transfer.json");var lineage=File.Exists(lineagePath)?HubRead(lineagePath):null;
  var expected=instances.ToDictionary(p=>p.Key,p=>(double[])p.Value.Transform2.ArrayData);var colors=instances.ToDictionary(p=>p.Key,p=>json.Serialize(new{component=p.Value.GetMaterialPropertyValues2(1,null),part=Owner(p.Key).MaterialPropertyValues}));
  var reviewedInstances=instances.Values.Select(c=>new InstanceRecord{Id=c.GetID(),Name=c.Name2,Path=c.GetPathName(),Reference=Ref(model,c)}).ToArray();
  var pack=model.Extension.GetPackAndGo();pack.IncludeDrawings=false;pack.IncludeSimulationResults=false;pack.IncludeSuppressed=true;pack.IncludeToolboxComponents=true;object values;if(!pack.GetDocumentNames(out values))throw new Exception("Cannot enumerate merge documents");var from=((object[])values).Cast<string>().ToArray();
  if(from.Any(p=>!Path.GetFullPath(p).StartsWith(folder+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)))throw new Exception("Review dependency outside isolated review");
  var stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss");var deps=Path.Combine(root,"hub-merged-"+stamp);var map=from.Select((p,i)=>new{From=p,To=string.Equals(p,original.Copy,StringComparison.OrdinalIgnoreCase)?target:Path.Combine(deps,i.ToString("D3")+"_"+Path.GetFileName(p))}).ToDictionary(p=>p.From,p=>p.To,StringComparer.OrdinalIgnoreCase);
  if(map.Values.Any(p=>!Path.GetFullPath(p).StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))||map.Values.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=map.Count)throw new Exception("Invalid merge destinations");
  if(!pack.SetDocumentSaveToNames(from.Select(p=>new BStrWrapper(map[p])).ToArray()))throw new Exception("Pack and Go refused destinations");
  var backup=Path.Combine(Path.GetDirectoryName(root),"before-hub-merge-"+stamp);Directory.CreateDirectory(backup);var backed=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);int index=0;
  foreach(var p in new[]{target}.Concat(Directory.GetFiles(root,"*.json"))){var dest=Path.Combine(backup,(index++).ToString("D3")+"_"+Path.GetFileName(p));File.Copy(p,dest,false);if(Hash(p)!=Hash(dest))throw new Exception("Backup mismatch");backed[p]=dest;}
  File.WriteAllText(Path.Combine(backup,"restore-map.json"),json.Serialize(backed));Write("hub-merge.json",new{status="backed_up",target=target,backup=backup});Console.WriteLine("Verified backup: "+backup);
  HubClose(oldPaths);bool writing=false;
  try{
   CheckOriginals();foreach(var b in backed)if(Hash(b.Key)!=Hash(b.Value))throw new Exception("Working metadata changed after backup");Directory.CreateDirectory(deps);writing=true;
   File.Move(target,Path.Combine(backup,"displaced-"+Path.GetFileName(target)));var status=model.Extension.SavePackAndGo(pack) as int[];Write("hub-merge-pack-status.json",status);if(status==null||status.Any(s=>s!=0)||map.Values.Any(p=>!File.Exists(p)))throw new Exception("Native merge failed");Console.WriteLine("Copied "+map.Count+" reviewed native documents");
   HubClose(new HashSet<string>(map.Keys,StringComparer.OrdinalIgnoreCase));HubOpen(target);
   if(instances.Count!=76||reviewedInstances.Any(c=>!instances.ContainsKey(c.Id)||!string.Equals(instances[c.Id].GetPathName(),map[c.Path],StringComparison.OrdinalIgnoreCase)))throw new Exception("Component structure changed");
   if(Mates().Count()!=71||MateFailures()!=0)throw new Exception("Merged mates unhealthy");var delta=instances.Max(p=>((double[])p.Value.Transform2.ArrayData).Zip(expected[p.Key],(a,b)=>Math.Abs(a-b)).Max());if(delta>1e-6)throw new Exception("Merged pose changed");
   if(instances.Any(p=>json.Serialize(new{component=p.Value.GetMaterialPropertyValues2(1,null),part=Owner(p.Key).MaterialPropertyValues})!=colors[p.Key]))throw new Exception("Merged appearance changed");
   oldInstances=reviewedInstances.ToDictionary(c=>c.Reference);rebound.Clear();bodyCache.Clear();record=new CopyRecord{Files=map};var project=(Dictionary<string,object>)RebindTree(reviewed);record=original;project["Identity"]=oldProject["Identity"];project["SourceDocument"]=target;if(oldProject.ContainsKey("FrameBuildReceipt"))project["FrameBuildReceipt"]=oldProject["FrameBuildReceipt"];foreach(var k in new[]{"LastBuildReceipt","PhysicsBuildReceipt","PhysicsTemplateReceipt"})project[k]="";
   var workspace=(Dictionary<string,object>)project["JointWorkspace"];workspace["ScanHash"]=null;workspace["ScanStamp"]=-1;workspace["ScanDocument"]=null;foreach(var m in HubArray(workspace,"Members"))m["PlacementFixed"]=((Component2)Resolve(model,(string)m["ComponentReference"])).IsFixed();
   if(HubValidate(project)!=1000||HubArray(project,"Components").Length!=68)throw new Exception("Merged assignment count changed");File.WriteAllText(target+".beamng-project.json",json.Serialize(project));
   var frames=HubArray(project,"Components").Where(g=>object.Equals(g["Template"],"calibrated_frame")).Select(g=>new{Id=g["Id"],Role="frame",Configuration=g["Configuration"],Selections=g["Selections"],Hull=g["Hull"]}).ToArray();var prep=json.Serialize(new{Format="beamng-cad-preparation",Version=1,SourceDocument=target,Assignments=frames});HubValidate(json.DeserializeObject(prep));File.WriteAllText(target+".truemesh-prep.json",prep);
   int mapped=0,provenance=0;Action<Dictionary<string,object>> visit=null;visit=g=>{
    object part;if(g.TryGetValue("Part",out part)&&part is string&&!string.IsNullOrEmpty((string)part)){var previous=original.Instances.Single(entry=>string.Equals(entry.Path,(string)part,StringComparison.OrdinalIgnoreCase));var c=instances[previous.Id];var oldPart=(string)part;g["Part"]=c.GetPathName();g["ComponentReference"]=Ref(model,c);mapped++;
     Dictionary<string,object> wheel;if(wheels.TryGetValue((string)g["Id"],out wheel)){var s=HubArray(wheel,"Selections");var keys=s.Select(b=>(string)b["ComponentReference"]+"|"+(string)b["Reference"]).ToArray();g["SourceBodies"]=keys;g["CopiedBodies"]=s.Select(b=>{var n=(string)b["Name"];return n.Substring(n.LastIndexOf(" / ",StringComparison.Ordinal)+3);}).ToArray();g["Scopes"]=new[]{new{Key="cad",Value=keys},new{Key="appearance",Value=keys}};g["SourceDocument"]=original.Copy;g["SourceProject"]=original.Copy+".beamng-project.json";g["SourceConfiguration"]=wheel["Configuration"];g["SourceOverride"]=true;g["NativePartCopy"]=true;g["AppearanceSnapshot"]=true;}
     object overridden;if(g.TryGetValue("SourceOverride",out overridden)&&object.Equals(overridden,true)&&HubArray(g,"Members").Length==0){var p=new{Format="beamng-association-assembly",Version=4,Status="completed",SourceDocument=g["SourceDocument"],SourceProject=g["SourceProject"],Configuration=g["SourceConfiguration"],Groups=new[]{g}};File.WriteAllText(c.GetPathName()+".appearance-provenance.json",json.Serialize(p));provenance++;}
     else if(File.Exists(oldPart+".appearance-provenance.json")){var p=File.ReadAllText(oldPart+".appearance-provenance.json");File.WriteAllText(c.GetPathName()+".appearance-provenance.json",p);}
    }foreach(var child in HubArray(g,"Members"))visit(child);
   };foreach(var g in HubArray(receipt,"Groups"))visit(g);receipt["Version"]=4;var notes=((object[])receipt["Notes"]).Select(Convert.ToString).ToList();notes.Add("Approved rear hub repair merged "+stamp+". Both wheel groups include rim, tire and restored rotating hub. Wheel source/appearance snapshots now use "+original.Copy+"; other group source ownership retained.");receipt["Notes"]=notes.ToArray();File.WriteAllText(Path.Combine(root,"working-assembly.json"),json.Serialize(receipt));
   if(lineage!=null){foreach(var g in HubArray(lineage,"Groups")){var previous=original.Instances.Single(entry=>string.Equals(entry.Path,(string)g["Part"],StringComparison.OrdinalIgnoreCase));var c=instances[previous.Id];g["Part"]=c.GetPathName();g["ComponentReference"]=Ref(model,c);var definition=HubArray(project,"Components").Single(v=>object.Equals(v["Id"],g["GroupId"]));object member;if(!g.TryGetValue("MemberId",out member)||member==null)g["Selections"]=definition["Selections"];else g["Selections"]=HubArray(workspace,"Members").Single(v=>object.Equals(v["Id"],member))["Selections"]; }lineage["HubRepairReview"]=original.Copy;File.WriteAllText(lineagePath,json.Serialize(lineage));}
   code.GetType("BeamNG.Cad.Preparation.VehicleProject",true).GetMethod("Load").Invoke(null,new object[]{target+".beamng-project.json"});Console.WriteLine("Rebound 1000 assignments; updated "+mapped+" receipt entries and "+provenance+" part provenance records");
   Save(model);HubClose(new HashSet<string>(map.Values,StringComparer.OrdinalIgnoreCase));HubOpen(target);if(Mates().Count()!=71||MateFailures()!=0||HubValidate(HubRead(target+".beamng-project.json"))!=1000)throw new Exception("Save/reopen validation failed");
   foreach(var g in HubArray(project,"Components").Where(g=>wheels.ContainsKey((string)g["Id"]))){var ss=HubArray(g,"Selections");var c=(Component2)Resolve(model,(string)ss[0]["ComponentReference"]);object info;var bodies=((object[])c.GetBodies3(-1,out info)).Cast<Body2>().ToArray();if(bodies.Length!=3)throw new Exception("Wheel body count changed after reopen");HubSeatCheck(bodies.Single(b=>b.Name.Contains("RestoredRearHub")));}
   if(original.Hashes.Any(p=>!string.Equals(p.Key,target,StringComparison.OrdinalIgnoreCase)&&Hash(p.Key)!=p.Value))throw new Exception("Old dependencies changed");
   Write("hub-merge.json",new{status="completed",target=target,backup=backup,dependency_folder=deps,mates=71,mate_failures=0,body_assignments=1000,instances=76,logical_groups=68,wheel_body_counts=new[]{3,3},rest_transform_max_delta=delta,appearance_preserved=true,identity_preserved=true,source_ownership_preserved=true,save_reopen_passed=true});
   model.ShowNamedView2("*Isometric",7);model.ViewZoomtofit2();model.GraphicsRedraw2();app.Visible=true;Console.WriteLine("PASS merged and reopened working companion: both hubs, 71 healthy mates, 1000 body assignments");
  }catch(Exception ex){record=original;if(writing){HubClose(new HashSet<string>(map.Values,StringComparer.OrdinalIgnoreCase));foreach(var b in backed)File.Copy(b.Value,b.Key,true);Write("hub-merge.json",new{status="rolled_back",target=target,backup=backup,error=ex.ToString(),unused_dependency_folder=deps});Console.WriteLine("Restored original working assembly and metadata from verified backup");}throw;}finally{record=original;}
 }
